CREATE TABLE #ProcResult (OrderID INT, Amount DECIMAL(18,2));
INSERT INTO #ProcResult (OrderID, Amount)
EXEC dbo.usp_GetTopOrders @TopN = 50;

DECLARE @Batch INT = 5000;
WHILE 1 = 1
BEGIN
    UPDATE TOP (@Batch) dbo.FactOrders
    SET IsArchived = 1
    WHERE OrderDate < '2025-01-01' AND IsArchived = 0;
    IF @@ROWCOUNT < @Batch BREAK;
    WAITFOR DELAY '00:00:00.100';
END;

DECLARE @Audit TABLE (Act NVARCHAR(10), SKU VARCHAR(50));
MERGE dbo.DimProd WITH (HOLDLOCK) AS t
USING dbo.StgProd AS s ON t.SKU = s.SKU
WHEN MATCHED THEN UPDATE SET t.Price = s.Price
WHEN NOT MATCHED THEN INSERT (SKU, Price) VALUES (s.SKU, s.Price)
OUTPUT $action, inserted.SKU INTO @Audit;
SELECT Act, COUNT(*) AS Cnt FROM @Audit GROUP BY Act;

DECLARE @NextNo BIGINT;
UPDATE dbo.SeqCounter
SET @NextNo = LastNo = LastNo + 1
WHERE SeqKey = 'INVOICE_2026';
SELECT @NextNo AS NewInvoiceNo;

SELECT OrderID,
       GREATEST(CreatedAt, PaidAt, ShippedAt) AS LatestEventTime
FROM dbo.FactOrders;

