CREATE TYPE dbo.OrderLineTvp AS TABLE (SKU VARCHAR(50), Qty INT);
GO
CREATE OR ALTER PROCEDURE dbo.usp_BulkInsertLines @Lines dbo.OrderLineTvp READONLY AS
BEGIN
